    ];

    /// <summary>Number of distinct retail enemy headers reachable from room states.</summary>
    public const int Count = 148;

    static RoomEnemyDefinitionCatalog()
    {
        if (Definitions.Length != Count)
            throw new InvalidDataException(
                $"Expected {Count} compiled enemy headers, found {Definitions.Length}.");
        for (int index = 1; index < Definitions.Length; index++)
        {
            if (Definitions[index - 1].Pointer >= Definitions[index].Pointer)
                throw new InvalidDataException(
                    $"Compiled enemy-header pointers are not strictly ordered at entry {index}.");
        }
    }

    /// <summary>Gets an application-owned retail header, rejecting unrecognized pointers.</summary>
    public static RoomEnemyDefinition Get(ushort pointer)
    {
        int low = 0;
        int high = Definitions.Length - 1;
        while (low <= high)
        {
            int middle = low + ((high - low) >> 1);
            var candidate = Definitions[middle];
            if (candidate.Pointer == pointer)
                return candidate.Definition;
            if (candidate.Pointer < pointer)
                low = middle + 1;
            else
                high = middle - 1;
        }

        throw new ArgumentOutOfRangeException(nameof(pointer), pointer,
            "Pointer is not a referenced retail bank-$A0 enemy definition.");
    }

    /// <summary>Enumerates every compiled native definition pointer for ROM-oracle tests.</summary>
    public static IEnumerable<ushort> Pointers => Definitions.Select(entry => entry.Pointer);
}
